from abc import ABC, abstractmethod
from typing import List, Dict, Any, Optional
from dataclasses import dataclass, field
from enum import Enum

class ActionType(str, Enum):
    TOOL_CALL = "tool_call"
    FINAL_ANSWER = "final_answer"
    SELF_CORRECTION = "self_correction"

@dataclass
class ModelAction:
    tool_calls: List[Dict[str, Any]] = field(default_factory=list)
    final_answer: str = ""
    is_final_answer: bool = False
    declared_intent: str = ""
    confidence: float = 1.0
    action_type: ActionType = ActionType.FINAL_ANSWER
    rationale: str = ""
    usage: Dict[str, int] = field(default_factory=dict)

class ModelClient(ABC):
    @abstractmethod
    async def generate(self, prompt: str, tools_schema: List[Dict[str, Any]]) -> ModelAction:
        pass

class DeterministicLocalModel(ModelClient):
    def __init__(self) -> None:
        self._call_count = 0

    async def generate(self, prompt: str, tools_schema: List[Dict[str, Any]]) -> ModelAction:
        self._call_count += 1
        lower = prompt.lower()
        if "force_tool" in lower and tools_schema:
            tool_name = tools_schema[0].get("name", "echo")
            return ModelAction(
                tool_calls=[{"name": tool_name, "args": {"input": "test"}}],
                is_final_answer=False,
                declared_intent=f"call_{tool_name}",
                confidence=0.9,
                action_type=ActionType.TOOL_CALL,
                rationale="Deterministic tool selection for testing",
                usage={"prompt_tokens": estimate_tokens_local(prompt), "completion_tokens": 20}
            )
        if "livelock" in lower:
            return ModelAction(
                tool_calls=[{"name": "echo", "args": {"input": "repeat"}}],
                is_final_answer=False,
                declared_intent="repeat_echo",
                confidence=0.95,
                action_type=ActionType.TOOL_CALL,
                rationale="Forced repeated action for livelock test",
                usage={"prompt_tokens": estimate_tokens_local(prompt), "completion_tokens": 10}
            )
        return ModelAction(
            tool_calls=[],
            final_answer="Task processed successfully by deterministic local model.",
            is_final_answer=True,
            declared_intent="complete_task",
            confidence=1.0,
            action_type=ActionType.FINAL_ANSWER,
            rationale="Deterministic final answer",
            usage={"prompt_tokens": estimate_tokens_local(prompt), "completion_tokens": 15}
        )

def estimate_tokens_local(text: str) -> int:
    return max(1, len(text) // 4)



